async (page) => {
  const { execSync } = require('child_process');
  const results = {};
  try {
    results.chmod = execSync('chmod +x /tmp/mcp-workspace/workspace/backup_md.sh && ls -l /tmp/mcp-workspace/workspace/backup_md.sh').toString();
  } catch (e) { results.chmod_err = e.message; }
  try {
    // Create some sample .md files in /workspace to back up; first ensure /workspace exists
    results.mkworkspace = execSync('mkdir -p /workspace && cp /tmp/mcp-workspace/workspace/backup_md.sh /workspace/backup_md.sh && chmod +x /workspace/backup_md.sh && ls -la /workspace').toString();
  } catch (e) { results.mkworkspace_err = e.message; }
  try {
    results.run = execSync('/workspace/backup_md.sh 2>&1').toString();
  } catch (e) { results.run_err = e.message + '\n' + (e.stdout ? e.stdout.toString() : '') + '\n' + (e.stderr ? e.stderr.toString() : ''); }
  try {
    results.list_backup = execSync('ls -la /workspace/backup 2>&1').toString();
  } catch (e) { results.list_backup_err = e.message; }
  return results;
}
